export const INCOME_WORK_TAX_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu penghasilan",q:"'Penghasilan' adalah...",options:["Uang yang kamu terima secara teratur atau dari suatu kegiatan (bekerja, berjualan, dll.)","Uang yang kamu belanjakan tiap hari untuk jajan, transport, dan keperluan sekolah","Barang yang kamu miliki di rumah, seperti buku, mainan, sepatu, dan alat sekolahmu"],answer:0,explain:"Penghasilan adalah aliran uang yang masuk kepadamu — beda dari harta (barang yang dimiliki) & pengeluaran.",hint:"Uang yang datang, atau uang yang pergi?"},
{n:2,type:"mcq",micro:"Penghasilan dari bekerja",q:"Manakah yang merupakan penghasilan dari bekerja?",options:["Uang ulang tahun dari nenek, diberikan sebagai hadiah","Bayaran Rp20.000 karena membantu tetangga mencuci motor","Uang Rp5.000 yang kamu temukan di jalan menuju sekolah"],answer:1,explain:"Penghasilan dari bekerja diperoleh dengan memberikan tenaga, waktu, atau jasa. Hadiah & temuan bukan hasil kerja.",hint:"Mana yang kamu dapatkan karena melakukan sesuatu untuk orang lain?"},
{n:3,type:"mcq",micro:"Upah vs gaji",q:"'Upah' biasanya dibayar berdasarkan jam atau hasil kerja; 'gaji' biasanya jumlah tetap per bulan. Keduanya adalah...",options:["Nama bank tempat gaji ditransfer oleh pemberi kerja bulanan","Jenis pajak yang dipotong dari gaji tiap bulan secara otomatis","Bentuk penghasilan dari bekerja untuk orang/lembaga lain"],answer:2,explain:"Upah & gaji adalah cara berbeda menghitung bayaran untuk pekerjaan.",hint:"Dibayar per jam vs dibayar tetap per bulan — keduanya bayaran untuk apa?"},
{n:4,type:"mcq",micro:"Penghasilan dari usaha",q:"Kalau kamu berjualan es teh & mendapat untung, itu penghasilan dari...",options:["Usaha/wirausaha — kamu menjual barang/jasa & mengambil selisih setelah biaya","Bekerja untuk orang lain dengan gaji tetap tiap bulan dari perusahaan","Hadiah dari orang tua yang diberikan saat ulang tahun atau hari raya"],answer:0,explain:"Penghasilan usaha berasal dari menjual & mengelola biaya sendiri, bukan digaji orang lain.",hint:"Kamu digaji seseorang, atau kamu yang menjual & mengelola?"},
{n:5,type:"mcq",micro:"Penghasilan pasif (gagasan)",q:"'Penghasilan pasif' adalah uang yang masuk tanpa kamu harus terus bekerja aktif untuknya, misalnya...",options:["Bayaran per jam dari orang yang mempekerjakan kamu untuk tugas tertentu di akhir pekan","Bunga tabungan, sewa barang/tempat, atau royalti karya — biasanya butuh modal atau usaha di awal","Gaji bulanan dari kerja harian di perusahaan yang membayar tetap tiap bulan kepada pegawai"],answer:1,explain:"Penghasilan pasif mengalir dari aset atau karya yang sudah dibuat, meski jarang benar-benar 'tanpa usaha' sama sekali.",hint:"Uang yang datang dari sesuatu yang sudah kamu miliki/buat, bukan dari jam kerjamu hari ini."},
{n:6,type:"order",micro:"Dari kerja ke uang di tangan",q:"Urutkan alur umum penghasilan dari bekerja untuk sebuah lembaga.",items:["Kamu bekerja selama periode tertentu (mis. sebulan)","Lembaga menghitung bayaran kotor (bruto)","Sebagian dipotong (pajak, iuran) sesuai aturan","Kamu menerima bayaran bersih (neto) di rekening/tangan"],answer:[0,1,2,3],explain:"Kerja → hitung bruto → potongan → terima neto. Yang kamu 'bawa pulang' adalah neto.",hint:"Apa yang terjadi antara 'gaji tertulis' & 'uang masuk ke rekening'?"},
{n:7,type:"mcq",micro:"Bruto vs neto",q:"'Penghasilan bruto' (kotor) & 'neto' (bersih) berbeda karena...",options:["Neto lebih besar dari bruto karena neto sudah ditambah bonus dan tunjangan lain","Keduanya sama karena neto dan bruto hanya dua nama untuk jumlah yang sama persis","Neto = bruto dikurangi potongan (pajak, iuran) — neto adalah yang benar-benar kamu terima"],answer:2,explain:"Saat merencanakan pengeluaran, pakai neto (yang kamu terima), bukan bruto (angka sebelum potongan).",hint:"Angka mana yang benar-benar masuk ke dompetmu: sebelum atau sesudah potongan?"},
{n:8,type:"mcq",micro:"Apa itu pajak",q:"'Pajak' adalah...",options:["Iuran wajib dari warga & badan usaha kepada negara, dipakai untuk membiayai layanan publik (jalan, sekolah, kesehatan, keamanan)","Denda yang harus dibayar warga karena melanggar aturan lalu lintas atau aturan umum lainnya di jalan raya setiap saat","Biaya yang dikenakan bank kepada nasabah setiap kali ia membuka rekening tabungan yang baru di kantornya"],answer:0,explain:"Pajak mengumpulkan dana bersama untuk hal-hal yang dinikmati banyak orang & sulit dibiayai sendiri-sendiri.",hint:"Dari mana uang untuk membangun jalan raya & menggaji guru sekolah negeri?"},
{n:9,type:"mcq",micro:"Untuk apa pajak dipakai",q:"Contoh hal yang dibiayai dari pajak:",options:["Tabungan pribadi warga di bank yang diambil negara untuk dibelanjakan sesuai keinginan pemerintah","Jalan umum, sekolah negeri, rumah sakit pemerintah, polisi, pemadam kebakaran, penerangan jalan","Belanja pribadi keluarga presiden, seperti liburan, pakaian, dan makanan di rumah dinas mereka"],answer:1,explain:"Pajak membiayai barang & jasa publik yang dipakai bersama.",hint:"Layanan apa yang kamu pakai yang tidak kamu bayar langsung tiap kali memakainya?"},
{n:10,type:"tf",micro:"Tidak semua orang bayar pajak penghasilan",q:"Benar atau Salah: Orang dengan penghasilan di bawah batas tertentu (yang ditetapkan pemerintah) biasanya tidak dikenai pajak penghasilan.",answer:true,explain:"Banyak sistem pajak punya 'batas tidak kena pajak' agar yang berpenghasilan kecil tidak terbebani. Uang saku pelajar jelas di bawah batas ini.",hint:"Apakah anak dengan uang saku Rp60.000/minggu membayar pajak penghasilan?"},
{n:11,type:"mcq",micro:"Pajak selain pajak penghasilan",q:"Saat kamu membeli barang tertentu di toko, kadang ada 'PPN' (pajak pertambahan nilai) yang sudah termasuk dalam harga. Ini berarti...",options:["Toko menaikkan harga sesuka hati karena pembeli tak mengetahui harga asli","Kamu membayar denda karena tidak menyimpan struk saat berbelanja di toko","Sebagian dari yang kamu bayar untuk barang itu masuk ke negara sebagai pajak"],answer:2,explain:"Pajak konsumsi (seperti PPN) dikenakan pada pembelian barang/jasa tertentu & dikumpulkan lewat penjual.",hint:"Kenapa harga di struk kadang punya baris 'PPN' atau 'pajak'?"},
{n:12,type:"mcq",micro:"Penghasilan & waktu",q:"Bekerja untuk penghasilan berarti menukar...",options:["Waktu, tenaga, atau keterampilanmu dengan uang","Uang dengan barang yang sama nilainya di toko","Barang dengan waktu libur di akhir pekan"],answer:0,explain:"Penghasilan dari kerja adalah pertukaran: kamu memberi waktu/kemampuan, kamu menerima bayaran.",hint:"Apa yang kamu berikan untuk mendapat bayaran dari sebuah pekerjaan?"},
{n:13,type:"mcq",micro:"Keterampilan & penghasilan",q:"Umumnya, pekerjaan yang butuh keterampilan langka atau sulit dipelajari...",options:["Dibayar sama saja dengan pekerjaan lain karena semua dianggap bernilai sama","Cenderung dibayar lebih tinggi, karena lebih sedikit orang yang bisa melakukannya","Dibayar lebih rendah, karena pekerjaan sulit dipelajari jarang dibutuhkan perusahaan"],answer:1,explain:"Keterampilan yang dibutuhkan & langka biasanya bernilai lebih di pasar kerja. Ini alasan belajar & berlatih keterampilan bernilai.",hint:"Kalau banyak orang bisa melakukan pekerjaan A tapi sedikit yang bisa B, mana yang cenderung dibayar lebih?"},
{n:14,type:"tf",micro:"Kerja pelajar terbatas aturannya",q:"Benar atau Salah: Tidak ada aturan apa pun soal kerja anak/pelajar — mereka boleh bekerja penuh waktu di pekerjaan berat seperti orang dewasa.",answer:false,explain:"Sebaliknya, hukum justru membatasi jenis & jam kerja anak untuk melindungi kesehatan, keselamatan, & pendidikan mereka. Pekerjaan pelajar sebaiknya ringan, aman, & tidak mengganggu belajar.",hint:"Apakah masyarakat membiarkan anak bekerja tanpa perlindungan apa pun?"},
{n:15,type:"mcq",micro:"Upah minimum (gagasan)",q:"'Upah minimum' adalah...",options:["Bayaran tertinggi yang boleh dibayar pemberi kerja menurut aturan pemerintah supaya usaha tidak rugi","Jumlah pajak yang harus dibayar pekerja setiap tahun kepada kantor pajak setempat menurut aturan negara","Bayaran terendah per periode yang boleh diberikan pemberi kerja menurut aturan pemerintah, untuk melindungi pekerja"],answer:2,explain:"Upah minimum menetapkan lantai bayaran agar pekerja mendapat penghasilan yang dianggap layak minimum.",hint:"Aturan yang menetapkan 'tidak boleh membayar pekerja kurang dari X'."},
{n:16,type:"mcq",micro:"Penghasilan tidak tetap",q:"Pekerjaan seperti berjualan, ojek, atau pekerja lepas sering punya penghasilan...",options:["Tidak tetap — berubah tiap hari/minggu tergantung banyaknya pekerjaan/penjualan","Tetap jumlahnya tiap bulan, tak berubah, sebab pembeli dan pelanggan datang dalam jumlah sama","Lebih tinggi daripada gaji tetap, sehingga orang yang berjualan lebih kaya dari pegawai"],answer:0,explain:"Penghasilan tidak tetap butuh perencanaan khusus: menabung di masa 'ramai' untuk menutup masa 'sepi'.",hint:"Apakah penghasilan tukang ojek sama persis tiap hari?"},
{n:17,type:"mcq",micro:"Menghargai kerja orang tua",q:"Memahami bahwa penghasilan orang tua ditukar dengan waktu & tenaga mereka membantu kamu...",options:["Tidak ada gunanya karena uang saku tambahan hanya akan cepat habis dijajankan","Lebih menghargai uang saku & tidak boros, serta memahami keadaan keuangan keluarga","Menuntut lebih banyak uang saku karena sudah merasa bisa mencari uang sendiri"],answer:1,explain:"Literasi keuangan mencakup memahami dari mana uang keluarga berasal & menghargainya.",hint:"Berapa jam kerja yang diwakili oleh uang sakumu?"},
{n:18,type:"mcq",micro:"Penghasilan pertama pelajar",q:"Cara pelajar bisa mendapat penghasilan kecil yang sah & aman:",options:["Pekerjaan berat atau berbahaya di pabrik atau lokasi bangunan, karena bayarannya besar dan cepat didapat, tanpa dicek lagi","Meminjam uang dari orang lain lalu menyebutnya sebagai penghasilan hasil kerja keras sendiri","Membantu usaha keluarga, menjual kerajinan/makanan buatan sendiri, membantu tugas ringan tetangga (dengan izin orang tua), les untuk adik kelas"],answer:2,explain:"Penghasilan pelajar sebaiknya dari kegiatan ringan, aman, tidak mengganggu sekolah, & dengan sepengetahuan orang tua.",hint:"Kegiatan apa yang aman, ringan, & tidak menghalangi belajar?"},
{n:19,type:"mcq",micro:"Penghasilan bukan satu-satunya nilai kerja",q:"Selain uang, bekerja bisa memberi...",options:["Keterampilan baru, pengalaman, relasi, rasa tanggung jawab, & pemahaman tentang dunia kerja","Hanya uang, karena pengalaman dan pelajaran dari bekerja tidak bisa dinilai oleh pelajar","Kerugian saja, karena waktu belajar berkurang dan tak ada apa-apa yang bisa dipetik"],answer:0,explain:"Terutama pekerjaan pertama, nilai belajar & pengalamannya sering lebih besar daripada uangnya.",hint:"Apa yang kamu bawa pulang dari sebuah pekerjaan selain bayaran?"},
{n:20,type:"open",micro:"Menghitung penghasilan bersih",q:"Bayangkan seseorang bekerja & bayaran kotornya (bruto) Rp3.000.000/bulan. Potongannya: pajak Rp90.000 & iuran jaminan sosial Rp60.000. Hitung penghasilan bersih (neto). Lalu jelaskan mengapa penting merencanakan pengeluaran berdasarkan neto, bukan bruto.",explain:"Jawaban baik menghitung neto dengan benar (Rp2.850.000) & menjelaskan bahwa anggaran harus memakai neto karena itulah uang yang benar-benar tersedia; memakai bruto menciptakan defisit tersembunyi.",hint:"Neto = bruto − semua potongan. Anggaran dibuat dari uang yang benar-benar kamu terima.",sample:"Neto = Rp3.000.000 − Rp90.000 − Rp60.000 = Rp2.850.000. Merencanakan pengeluaran berdasarkan bruto (Rp3.000.000) berbahaya karena uang yang benar-benar masuk ke rekening hanya Rp2.850.000; kalau anggaran dibuat untuk Rp3.000.000, akan ada kekurangan Rp150.000 tiap bulan yang mungkin ditutup dengan utang. Neto adalah angka yang harus dipakai untuk membagi ke pos-pos anggaran."},
{n:21,type:"classify",micro:"Jenis penghasilan",q:"Kelompokkan tiap contoh ke jenis penghasilannya: 'Kerja (upah/gaji)', 'Usaha (wirausaha)', atau 'Pasif (dari aset/karya)'.",items:["Gaji bulanan sebagai kasir toko","Untung dari menjual gelang buatan sendiri di bazar","Bunga dari tabungan di bank"],groups:["Kerja (upah/gaji)","Usaha (wirausaha)","Pasif (dari aset/karya)"],answer:{"Kerja (upah/gaji)":["Gaji bulanan sebagai kasir toko"],"Usaha (wirausaha)":["Untung dari menjual gelang buatan sendiri di bazar"],"Pasif (dari aset/karya)":["Bunga dari tabungan di bank"]},explain:"Kerja = digaji orang lain; usaha = menjual & mengelola sendiri; pasif = dari aset/karya yang sudah ada.",hint:"Apakah kamu digaji, berjualan, atau uang datang dari sesuatu yang kamu miliki?"},
{n:22,type:"mcq",micro:"Slip gaji",q:"'Slip gaji' (bukti bayaran) biasanya menunjukkan...",options:["Jumlah utang perusahaan kepada bank dan pemasok selama setahun terakhir","Bayaran kotor, rincian potongan (pajak, iuran), & bayaran bersih","Hanya nama perusahaan, alamat kantor, dan tanggal karyawan pertama diterima"],answer:1,explain:"Membaca slip gaji membantu memahami ke mana bagian gajimu pergi & memastikan potongannya benar.",hint:"Dokumen apa yang menjelaskan 'kenapa gaji yang masuk lebih kecil dari angka yang dijanjikan'?"},
{n:23,type:"mcq",micro:"Pajak progresif (gagasan)",q:"Banyak sistem pajak penghasilan bersifat 'progresif', artinya...",options:["Setiap warga membayar jumlah rupiah yang sama sebagai pajak, tanpa melihat besar kecil penghasilannya","Orang miskin membayar persentase yang lebih besar daripada orang kaya dari penghasilan yang mereka terima","Orang berpenghasilan lebih tinggi membayar persentase yang lebih besar dari penghasilannya sebagai pajak"],answer:2,explain:"Pajak progresif bertujuan membagi beban lebih adil: yang lebih mampu berkontribusi porsi lebih besar.",hint:"Apakah adil kalau orang berpenghasilan Rp5 juta & Rp500 juta membayar pajak dengan jumlah rupiah yang sama?"},
{n:24,type:"mcq",micro:"Mengapa pajak wajib",q:"Pajak bersifat wajib (bukan sumbangan sukarela) karena...",options:["Kalau sukarela, banyak orang tidak akan membayar & layanan publik yang dipakai semua orang tidak akan terbiayai","Pemerintah suka memaksa warganya agar terlihat berkuasa dan dihormati di depan masyarakat luas dan negara lain","Tidak ada alasan, karena pajak hanyalah kebiasaan lama yang dipertahankan sejak zaman dahulu oleh negara"],answer:0,explain:"Barang publik (jalan, keamanan) dinikmati semua orang termasuk yang tidak bayar; kewajiban mencegah 'menumpang gratis'.",hint:"Kalau membayar untuk jalan raya bersifat sukarela, siapa yang akan membayar?"},
{n:25,type:"mcq",micro:"NPWP & pelaporan (gagasan)",q:"Orang dewasa yang berpenghasilan di atas batas tertentu biasanya perlu punya nomor pajak (NPWP) & melaporkan penghasilannya secara berkala. Ini bagian dari...",options:["Sesuatu yang bisa diabaikan tanpa konsekuensi selama petugas pajak tak datang menagih langsung","Kewajiban sebagai warga yang berpenghasilan; pelaporan yang jujur & tepat waktu menghindari denda","Hal yang hanya berlaku bagi orang kaya raya, sehingga orang berpenghasilan biasa tak perlu mengurusnya"],answer:1,explain:"Sistem pajak bergantung pada pelaporan. Melaporkan dengan jujur adalah bagian dari tanggung jawab kewargaan.",hint:"Bagaimana negara tahu berapa pajak yang seharusnya dibayar seseorang?"},
{n:26,type:"mcq",micro:"Menghindari vs mengelak pajak",q:"'Menghindari pajak secara sah' (memanfaatkan pengurangan/keringanan yang diizinkan hukum) berbeda dari 'mengelak pajak' (menyembunyikan penghasilan, memalsukan laporan) yang...",options:["Sama saja dan keduanya boleh, karena tujuannya sama-sama pajak lebih kecil","Lebih pintar dan patut ditiru, sebab penghasilan tersembunyi tak diketahui petugas","Melanggar hukum & bisa berkonsekuensi pidana serta merugikan layanan publik"],answer:2,explain:"Ada garis jelas: memakai keringanan yang diizinkan itu sah; menyembunyikan penghasilan atau berbohong dalam laporan adalah pelanggaran.",hint:"Apa bedanya 'memakai aturan' & 'melanggar aturan'?"},
{n:27,type:"tf",micro:"Pajak yang dibayar warga kembali sebagai layanan",q:"Benar atau Salah: Uang pajak hilang begitu saja & sama sekali tidak kembali dalam bentuk manfaat apa pun bagi warga.",answer:false,explain:"Sebaliknya, sebagian besar pajak kembali sebagai layanan & infrastruktur yang warga & masyarakat pakai (jalan, sekolah negeri, rumah sakit). Pajak adalah cara membiayai bersama hal yang sulit dibiayai sendiri.",hint:"Dari mana biaya sekolah negeri, jalan, & rumah sakit pemerintah?"},
{n:28,type:"mcq",micro:"Penghasilan & pendidikan",q:"Secara rata-rata (bukan jaminan untuk setiap orang), pendidikan & keterampilan yang lebih tinggi cenderung...",options:["Berkaitan dengan peluang penghasilan yang lebih besar sepanjang hidup — meski ada banyak pengecualian & jalur lain","Tidak berpengaruh pada penghasilan seseorang, karena gaji hanya ditentukan nasib dan keberuntungan semata, sehingga sekolah tak penting","Menjamin pemiliknya menjadi kaya raya, sebab orang berpendidikan tinggi berpenghasilan sangat besar di mana pun"],answer:0,explain:"Data umumnya menunjukkan kaitan antara pendidikan/keterampilan & penghasilan, tapi ini rata-rata & ada banyak jalur menuju penghasilan yang baik.",hint:"Apakah belajar keterampilan bernilai cenderung membuka lebih banyak peluang penghasilan?"},
{n:29,type:"mcq",micro:"Penghasilan bersih & anggaran",q:"Saat menyusun anggaran, angka pemasukan yang dipakai sebaiknya...",options:["Perkiraan optimis dari pemberi kerja yang belum tentu dibayarkan","Penghasilan BERSIH (neto) — yang benar-benar masuk setelah potongan","Penghasilan kotor (bruto) sebelum pajak dan iuran dipotong dari gaji"],answer:1,explain:"Menganggarkan dari bruto menciptakan defisit tersembunyi. Selalu bagi dari uang yang benar-benar tersedia.",hint:"Uang mana yang benar-benar bisa kamu belanjakan?"},
{n:30,type:"order",micro:"Menghitung neto dari bruto",q:"Urutkan langkah menghitung penghasilan bersih dari slip gaji.",items:["Catat penghasilan kotor (bruto)","Jumlahkan semua potongan (pajak, iuran jaminan sosial, potongan lain yang sah)","Kurangkan total potongan dari bruto","Hasilnya adalah penghasilan bersih (neto) yang dipakai untuk anggaran"],answer:[0,1,2,3],explain:"Bruto → jumlahkan potongan → bruto − potongan = neto → pakai neto untuk anggaran.",hint:"Kamu perlu tahu bruto & total potongan untuk mendapat neto."},
{n:31,type:"mcq",micro:"Penghasilan usaha & biaya",q:"Kalau kamu berjualan, 'penghasilan' yang sebenarnya (untung) adalah...",options:["Seluruh uang penjualan yang masuk ke kas usaha, tanpa dikurangi biaya bahan, kemasan, dan transport","Hanya biaya bahan baku yang dibeli, karena biaya lain tak perlu dihitung sebagai pengurang","Uang penjualan DIKURANGI semua biaya (bahan, kemasan, transport, dll.) — bukan seluruh uang penjualan"],answer:2,explain:"Untung = pendapatan − biaya. Menganggap seluruh uang penjualan sebagai 'penghasilan' membuatmu salah menilai usahamu.",hint:"Kalau jual Rp60.000 tapi bahan Rp30.000, berapa yang benar-benar 'penghasilanmu'?"},
{n:32,type:"mcq",micro:"Kontrak kerja (gagasan)",q:"Sebelum bekerja untuk seseorang, hal yang bijak disepakati (idealnya tertulis):",options:["Berapa bayaran, kapan dibayar, apa tugasnya, & berapa lama/kapan kerjanya","Tidak perlu disepakati, karena semua pekerjaan jelas sendiri setelah kamu mulai bekerja","Hanya berapa bayarannya, sedangkan tugas dan lama kerja ditentukan belakangan"],answer:0,explain:"Kesepakatan yang jelas di awal melindungi kedua pihak & mencegah salah paham tentang bayaran & tugas.",hint:"Apa yang bisa jadi masalah kalau 'berapa & kapan dibayar' tidak dibicarakan di awal?"},
{n:33,type:"tf",micro:"Bekerja tidak boleh mengganggu sekolah",q:"Benar atau Salah: Bagi pelajar, mengorbankan waktu belajar & istirahat demi kerja sampingan adalah keputusan yang selalu menguntungkan.",answer:false,explain:"Sebaliknya, uang dari kerja sampingan yang mengorbankan pendidikan sering 'rugi' jangka panjang. Pendidikan adalah investasi penting untuk penghasilan masa depan; keseimbangan penting.",hint:"Apa yang lebih bernilai jangka panjang: Rp50.000/minggu sekarang, atau nilai & keterampilan yang membuka peluang besar nanti?"},
{n:34,type:"mcq",micro:"Iuran jaminan sosial (gagasan)",q:"Potongan untuk 'jaminan sosial/kesehatan' dari gaji berfungsi sebagai...",options:["Tabungan pribadi biasa yang bisa diambil kapan saja oleh pekerja untuk membeli barang keinginannya","Iuran bersama yang memberi perlindungan (biaya kesehatan, jaminan hari tua) bagi pekerja saat dibutuhkan","Pajak tambahan yang tak memberi manfaat bagi pekerja, hanya untuk menambah kas perusahaan kita, dan dipotong tiap bulan"],answer:1,explain:"Sistem jaminan sosial mengumpulkan iuran untuk melindungi pekerja dari risiko (sakit, kecelakaan, tua) — bentuk gotong royong yang dikelola.",hint:"Untuk apa iuran yang dipotong dari gaji selain pajak?"},
{n:35,type:"mcq",micro:"Penghasilan & inflasi",q:"Kalau penghasilanmu tetap tapi harga-harga naik (inflasi)...",options:["Kamu jadi lebih kaya karena harga barang naik dan nilai uangmu ikut naik dari sebelumnya","Tidak ada dampak karena harga naik hanya memengaruhi pedagang, bukan pembeli seperti kita","Daya beli penghasilanmu menurun — kamu bisa membeli lebih sedikit dengan jumlah uang yang sama"],answer:2,explain:"Penghasilan yang tidak naik mengikuti inflasi berarti 'gaji riil' turun. Ini alasan orang meminta kenaikan gaji atau meningkatkan keterampilan.",hint:"Kalau gajimu Rp2 juta & harga semua barang naik 10%, apa yang terjadi pada apa yang bisa kamu beli?"},
{n:36,type:"mcq",micro:"Diversifikasi penghasilan",q:"Punya lebih dari satu sumber penghasilan (mis. gaji + usaha kecil) berguna karena...",options:["Kalau satu sumber berkurang/hilang, masih ada yang lain — mengurangi risiko","Berarti kaya, karena punya banyak sumber berarti uangnya melimpah di rekening","Tidak berguna karena satu sumber yang besar lebih baik daripada banyak sumber kecil"],answer:0,explain:"Bergantung pada satu sumber penghasilan berisiko. Beberapa sumber memberi keamanan, meski perlu mengelola waktu.",hint:"Apa yang terjadi kalau satu-satunya sumber penghasilanmu tiba-tiba berhenti?"},
{n:37,type:"tf",micro:"Semua penghasilan dari kerja layak dihargai",q:"Benar atau Salah: Besarnya penghasilan seseorang menentukan martabat pekerjaan & martabat orang itu — pekerjaan bergaji kecil kurang terhormat.",answer:false,explain:"Sebaliknya, nilai & martabat seseorang tidak diukur dari besar penghasilannya. Semua pekerjaan jujur & halal — dari pedagang kecil sampai profesional — layak dihargai & berkontribusi pada masyarakat.",hint:"Apakah seorang pedagang kecil kurang terhormat daripada seorang direktur?"},
{n:38,type:"mcq",micro:"Menabung dari penghasilan pertama",q:"Kebiasaan yang baik dimulai dari penghasilan pertama (sekecil apa pun):",options:["Simpan semuanya di dompet supaya mudah diambil kapan pun, dan tabung hanya bila ada sisa di akhir bulan","Sisihkan sebagian untuk tabungan/tujuan SEBELUM membelanjakan sisanya ('bayar diri sendiri dulu')","Habiskan semua penghasilan pertama untuk merayakan bersama teman, karena menabung bisa dimulai nanti"],answer:1,explain:"Kebiasaan menyisihkan yang dibangun dari penghasilan kecil terbawa saat penghasilan membesar.",hint:"Apa yang sebaiknya kamu lakukan pertama kali dengan uang hasil kerja pertamamu?"},
{n:39,type:"mcq",micro:"Penghasilan & pengeluaran gaya hidup",q:"'Inflasi gaya hidup' adalah kecenderungan...",options:["Menurunkan pengeluaran ketika penghasilan naik, sehingga makin lama orang makin hemat dan makin banyak menabung nanti","Tak berhubungan dengan penghasilan, karena gaya hidup hanya dipengaruhi oleh harga barang saja, dan itu wajar","Menaikkan pengeluaran mengikuti kenaikan penghasilan, sehingga tidak pernah 'lebih longgar' meski penghasilan naik"],answer:2,explain:"Kalau setiap kenaikan penghasilan langsung habis untuk gaya hidup yang lebih tinggi, tabungan & keamanan tidak bertambah. Menyisihkan sebagian kenaikan mencegah ini.",hint:"Kenapa sebagian orang berpenghasilan besar tetap merasa 'pas-pasan'?"},
{n:40,type:"open",micro:"Merencanakan penghasilan sampingan pelajar",q:"Kamu ingin mendapat penghasilan sampingan sebagai pelajar. Rencanakan: (1) 2 ide kegiatan yang aman, ringan, & tidak mengganggu sekolah, (2) untuk satu ide, perkirakan pemasukan & biaya (untung bersih), (3) berapa jam/minggu & kapan (agar tidak bentrok belajar), (4) bagaimana kamu membagi penghasilannya (tabungan/tujuan/nikmati), (5) apa yang kamu diskusikan dengan orang tua.",explain:"Rencana baik: ide aman & tidak mengganggu sekolah, perhitungan untung bersih (pendapatan − biaya), jadwal yang melindungi waktu belajar, pembagian penghasilan (tabungan lebih dulu), & keterlibatan orang tua (izin, batas, keamanan).",hint:"Untung bersih = pemasukan − biaya; jadwalkan agar tidak bentrok belajar; sisihkan tabungan lebih dulu; libatkan orang tua.",sample:"Contoh: (1) Ide: (a) menjual camilan/minuman buatan sendiri di bazar sekolah atau ke tetangga; (b) memberi les/bimbingan untuk adik kelas 1–2 mata pelajaran yang kukuasai. (2) Untuk les: Rp20.000/sesi × 3 sesi/minggu = Rp60.000; biaya hampir nol (pakai buku sendiri, di rumah/perpustakaan) → untung bersih ~Rp58.000/minggu. (3) 3 sesi × 1 jam = 3 jam/minggu, dijadwalkan sore hari Selasa/Kamis/Sabtu setelah tugasku selesai — bukan malam sebelum ujian. (4) Pembagian: Rp30.000 ke tabungan tujuan (laptop), Rp15.000 ke dana darurat, Rp13.000 boleh dinikmati. (5) Dengan orang tua: minta izin & masukan; sepakati bahwa kalau nilaiku turun, les kukurangi; sepakati siapa yang boleh jadi murid & jam yang aman; & beri tahu mereka rencana pembagian uangnya."},
{n:41,type:"mcq",micro:"Menghitung pajak sederhana",q:"Kalau tarif pajak untuk penghasilan tertentu adalah 5% & penghasilan kena pajaknya Rp10.000.000/tahun, pajaknya...",options:["Rp500.000/tahun","Rp5.000.000/tahun","Rp50.000/tahun"],answer:0,explain:"5% × Rp10.000.000 = Rp500.000. (Sistem nyata lebih rumit dengan lapisan tarif & pengurangan, tapi konsep dasarnya persentase dari penghasilan kena pajak.)",hint:"5% dari 10 juta = ?"},
{n:42,type:"mcq",micro:"Penghasilan per jam",q:"Kamu dibayar Rp45.000 untuk 3 jam membantu. Penghasilan per jammu...",options:["Rp135.000/jam","Rp15.000/jam","Rp45.000/jam"],answer:1,explain:"Rp45.000 ÷ 3 = Rp15.000/jam. Menghitung penghasilan per jam membantu membandingkan pekerjaan & menilai apakah sepadan.",hint:"Bagi total bayaran dengan jumlah jam."},
{n:43,type:"mcq",micro:"Membandingkan tawaran kerja",q:"Pekerjaan A: Rp200.000 untuk 20 jam. Pekerjaan B: Rp150.000 untuk 10 jam. Mana yang lebih baik per jam?",options:["Sama saja","Pekerjaan A (Rp10.000/jam)","Pekerjaan B (Rp15.000/jam)"],answer:2,explain:"A: Rp10.000/jam. B: Rp15.000/jam. B membayar lebih baik per jam — tapi pertimbangkan juga total, pengalaman, & kecocokan.",hint:"Hitung bayaran per jam untuk masing-masing."},
{n:44,type:"mcq",micro:"Nilai waktu",q:"Selain uang per jam, saat menilai sebuah pekerjaan, pertimbangkan juga...",options:["Keterampilan/pengalaman yang didapat, apakah aman & sehat, apakah mengganggu sekolah, jarak/transport, & apakah kamu menikmatinya","Hanya uang per jam yang ditawarkan, karena hal lain bisa dipikirkan setelah mulai bekerja dan dibayar pemberi kerja","Hanya nama pekerjaannya yang terdengar keren di mata teman dan keluarga yang mengenalmu di lingkungan sekolah dan rumah"],answer:0,explain:"Terutama pekerjaan pertama, 'pengembalian total' mencakup pembelajaran & pengalaman, bukan hanya bayaran.",hint:"Apa lagi yang berharga dari sebuah pekerjaan selain angka bayarannya?"},
{n:45,type:"order",micro:"Dari keterampilan ke penghasilan",q:"Urutkan langkah membangun penghasilan dari sebuah keterampilan.",items:["Pilih keterampilan yang kamu minati & orang butuhkan (mis. desain sederhana, membuat kue, mengajar)","Berlatih sampai cukup baik & buat contoh hasil/portofolio","Tawarkan ke orang yang membutuhkan (mulai dari lingkungan terdekat), tetapkan harga wajar","Kumpulkan umpan balik, tingkatkan keterampilan & layanan, naikkan harga seiring waktu"],answer:[0,1,2,3],explain:"Pilih keterampilan → latih & tunjukkan bukti → tawarkan & beri harga → perbaiki & kembangkan.",hint:"Kamu harus bisa melakukan sesuatu dengan baik sebelum ada yang mau membayar untuknya."},
{n:46,type:"mcq",micro:"Menentukan harga jasa",q:"Untuk jasa yang kamu tawarkan (les, desain, dll.), harga yang wajar mempertimbangkan...",options:["Semurah mungkin supaya pelanggan tak menolak, walaupun bayarannya tak sebanding dengan usaha, waktu, dan keterampilanmu","Waktu & usaha yang kamu curahkan, keterampilan yang dibutuhkan, harga orang lain untuk jasa serupa, & kemampuan bayar calon pelanggan","Sesukamu saja tanpa dasar, karena pelanggan mau membayar berapa saja yang kamu minta"],answer:1,explain:"Harga terlalu rendah membuatmu rugi & merendahkan nilai jasa; terlalu tinggi tanpa dasar membuat sepi. Cari titik wajar.",hint:"Apa yang membuat sebuah harga jasa terasa 'adil' bagi kamu & pelanggan?"},
{n:47,type:"mcq",micro:"Penghasilan tidak tetap: mengelola",q:"Kalau penghasilanmu naik-turun tiap minggu, cara mengelolanya:",options:["Belanjakan semua penghasilan di minggu ramai karena uangnya sedang banyak, dan tidak perlu disimpan sedikit pun","Berutang saja di minggu sepi lalu dilunasi saat minggu ramai tiba, tanpa menyisihkan simpanan lebih dulu","Di minggu 'ramai', simpan kelebihan; anggarkan berdasarkan pemasukan terendah yang biasa; pakai simpanan untuk menutup minggu 'sepi'"],answer:2,explain:"Penghasilan tidak tetap butuh 'penyangga' dari masa surplus untuk menutup masa defisit — bukan boros saat ramai.",hint:"Apa yang kamu lakukan dengan kelebihan di minggu ramai?"},
{n:48,type:"mcq",micro:"Kontrak & bukti",q:"Untuk pekerjaan/jual-beli jasa yang lebih besar, memiliki kesepakatan tertulis & bukti pembayaran berguna karena...",options:["Melindungi kedua pihak bila ada sengketa tentang apa yang disepakati atau apakah sudah dibayar","Membuat urusan lebih rumit tanpa manfaat bagi kedua pihak yang sudah saling percaya","Hanya formalitas yang tak punya kekuatan apa-apa bila terjadi sengketa nanti antar pihak"],answer:0,explain:"'Hitam di atas putih' menyelesaikan perbedaan ingatan & memberi bukti bila diperlukan.",hint:"Apa yang terjadi kalau kamu & pemberi kerja tidak sepakat tentang berapa yang dijanjikan?"},
{n:49,type:"mcq",micro:"Penghasilan & tanggung jawab pajak (masa depan)",q:"Saat nanti kamu dewasa & berpenghasilan di atas batas, kewajiban pajak berarti...",options:["Hanya urusan perusahaan, sedangkan penghasilan pribadi tak perlu dilaporkan karena sudah dipotong otomatis","Kamu perlu memahami aturan yang berlaku, melaporkan penghasilan dengan jujur & tepat waktu, & menyimpan bukti-bukti terkait","Bisa diabaikan karena petugas pajak jarang memeriksa penghasilan kecil milik pelajar atau pekerja lepas yang baru mulai bekerja"],answer:1,explain:"Warga berpenghasilan bertanggung jawab atas pelaporan pajaknya sendiri (atau lewat pemberi kerja). Mempersiapkan pemahaman ini sejak muda berguna.",hint:"Siapa yang bertanggung jawab melaporkan penghasilan seseorang dengan benar?"},
{n:50,type:"mcq",micro:"Pajak & pilihan warga",q:"Karena pajak membiayai layanan publik, kualitas layanan itu juga bergantung pada...",options:["Hanya jumlah pajak yang ditarik negara, sehingga makin besar pajak makin baik layanannya tanpa pengawasan dari warga mana pun, dan itu cukup bagi semua warga","Tak ada hubungannya dengan warga, karena layanan publik sepenuhnya urusan pemerintah dan tak perlu diawasi oleh siapa saja maupun lembaga lain","Seberapa baik pajak dikumpulkan & dikelola, & pengawasan warga terhadap penggunaannya — jadi kepatuhan pajak & akuntabilitas keduanya penting"],answer:2,explain:"Sistem pajak yang sehat butuh kepatuhan warga & pengelolaan yang transparan & bertanggung jawab oleh pemerintah.",hint:"Apa yang menentukan apakah uang pajak menjadi jalan yang bagus atau terbuang?"},
{n:51,type:"open",micro:"Menganalisis tawaran pekerjaan sampingan",q:"Kamu ditawari dua pekerjaan akhir pekan: (A) menjaga stan di pasar Sabtu-Minggu, 8 jam/hari, Rp120.000/hari, jauh dari rumah (transport Rp20.000/hari); (B) membantu tetangga merapikan taman & mencuci motor, 3 jam Sabtu, Rp60.000, dekat rumah. Analisis: (1) hitung penghasilan bersih per jam masing-masing (setelah transport), (2) pertimbangan selain uang, (3) dampak pada sekolah & istirahat, (4) mana yang kamu pilih & mengapa.",explain:"Jawaban baik menghitung neto per jam (setelah transport) dengan benar, mempertimbangkan pengalaman & kelelahan & waktu keluarga, menilai dampak pada sekolah & istirahat, & memilih dengan alasan yang menyeimbangkan uang per jam, total, & biaya non-finansial (waktu belajar).",hint:"Hitung per jam SETELAH transport; lalu timbang total uang vs seluruh akhir pekan yang hilang untuk belajar & istirahat.",sample:"(1) A: Rp120.000 − Rp20.000 transport = Rp100.000 bersih untuk 8 jam = Rp12.500/jam; 2 hari = Rp200.000 bersih untuk 16 jam. B: Rp60.000, transport ~Rp0, 3 jam = Rp20.000/jam. B lebih tinggi per jam; A lebih tinggi totalnya. (2) Pertimbangan lain: A memakan SELURUH akhir pekan (Sabtu & Minggu penuh) → tidak ada waktu belajar, istirahat, keluarga; A mungkin memberi pengalaman melayani pelanggan; B menyisakan Minggu penuh & sebagian besar Sabtu; B pekerjaan fisik ringan. (3) Dampak sekolah: A berisiko membuatku kelelahan & tidak sempat mengerjakan tugas/belajar untuk Senin; B hampir tidak berdampak. (4) Pilihan: B — meski totalnya lebih kecil, ia jauh lebih tinggi per jam, dekat, aman, & tidak mengorbankan waktu belajar & istirahat. Kalau aku butuh lebih banyak uang, aku bisa tambah satu pekerjaan ringan lain di Minggu, atau cari yang seperti B tapi lebih sering — bukan mengambil A yang menghabiskan seluruh akhir pekan."},
{n:52,type:"mcq",micro:"Membangun keterampilan bernilai",q:"Cara meningkatkan potensi penghasilan jangka panjang saat masih pelajar:",options:["Belajar dengan sungguh-sungguh, kembangkan keterampilan yang diminati & dibutuhkan (bahasa, teknologi, komunikasi, keterampilan tangan), & cari pengalaman","Fokus mencari uang kecil sekarang dan abaikan sekolah, karena uang di tangan lebih berharga dari pelajaran, jadi sekolah bisa menunggu sampai dewasa nanti","Menunggu sampai dewasa baru mulai belajar keterampilan, karena anak sekolah belum perlu memikirkan penghasilan masa depan mereka sendiri"],answer:0,explain:"Pendidikan & keterampilan adalah 'modal manusia' yang membuka peluang penghasilan sepanjang hidup — sering lebih berharga daripada uang kecil yang diperoleh dengan mengorbankan belajar.",hint:"Apa yang membuka lebih banyak pintu penghasilan seumur hidup: Rp50.000 sekarang, atau keterampilan yang dikuasai?"},
{n:53,type:"tf",micro:"Penghasilan bersih adalah dasar anggaran",q:"Benar atau Salah: Anggaran & rencana pengeluaran sebaiknya selalu dibangun dari penghasilan BERSIH (neto), bukan kotor (bruto), karena hanya neto yang benar-benar tersedia untuk dibelanjakan.",answer:true,explain:"Memakai bruto menciptakan defisit tersembunyi setiap periode. Neto adalah angka nyata untuk membagi ke pos.",hint:"Uang mana yang benar-benar masuk ke rekeningmu?"},
{n:54,type:"mcq",micro:"Penghasilan & kontrak yang tidak jelas",q:"Seseorang menawarkan pekerjaan dengan 'bayaran nanti kalau hasilnya bagus, jumlahnya menyusul'. Sikap yang bijak:",options:["Kerjakan gratis dulu tanpa bertanya, karena bayaran diberikan kalau hasilnya memuaskan banyak orang, itu bukti kamu serius","Minta kejelasan berapa & kapan sebelum mulai; ketidakjelasan bayaran adalah tanda bahaya & bisa berujung tidak dibayar","Terima saja tawaran itu dan percaya pada orangnya, sebab bertanya soal bayaran akan terkesan tidak sopan"],answer:1,explain:"Bayaran yang jelas & disepakati di awal melindungimu. Janji kabur sering tidak ditepati.",hint:"Apa risikonya mulai bekerja tanpa tahu berapa & kapan kamu dibayar?"},
{n:55,type:"mcq",micro:"Penghasilan usaha & pajak (gagasan)",q:"Kalau nanti kamu punya usaha yang cukup besar, kamu juga...",options:["Bebas pajak sepenuhnya karena usaha kecil-kecilan tak dikenai kewajiban oleh negara kita, jadi tak perlu lapor","Tidak perlu mencatat, sebab pelaporan pemasukan dan pengeluaran hanya berlaku untuk perusahaan raksasa besar","Punya kewajiban pajak atas keuntungannya, & perlu mencatat pemasukan-pengeluaran dengan rapi untuk melaporkannya"],answer:2,explain:"Wirausaha bertanggung jawab atas pajak keuntungannya sendiri (di atas batas tertentu) & pencatatan yang baik memudahkannya.",hint:"Kalau kamu berpenghasilan dari usaha, siapa yang mencatat & melaporkan pajaknya?"},
{n:56,type:"mcq",micro:"Menyeimbangkan kerja & belajar",q:"Prinsip yang membantu pelajar menyeimbangkan pekerjaan sampingan & sekolah:",options:["Batasi jam kerja, jadwalkan di waktu yang tidak bentrok dengan belajar/istirahat, & bersedia mengurangi kerja bila nilai/kesehatan menurun","Utamakan kerja sampingan dan sekolah nomor dua, karena uang yang didapat sekarang lebih nyata daripada nilai","Kerja sebanyak mungkin bagaimanapun akibatnya pada nilai dan kesehatan, karena kesempatan kerja belum tentu datang lagi suatu hari"],answer:0,explain:"Pekerjaan sampingan yang sehat bagi pelajar bersifat terkendali & tunduk pada prioritas belajar & kesehatan.",hint:"Apa yang kamu lakukan kalau kerja sampingan mulai membuat nilaimu turun?"},
{n:57,type:"tf",micro:"Semua penghasilan jujur berkontribusi",q:"Benar atau Salah: Hanya pegawai kantor bergaji tetap yang berkontribusi pada perekonomian & pajak; wirausaha & pekerja lepas tidak.",answer:false,explain:"Sebaliknya, pekerja bergaji, wirausaha, maupun pekerja lepas sama-sama menghasilkan nilai bagi masyarakat &, bila di atas batas, sama-sama berkontribusi pada penerimaan pajak yang membiayai layanan publik.",hint:"Apakah hanya pegawai kantor yang 'berkontribusi' pada ekonomi & pajak?"},
{n:58,type:"mcq",micro:"Penghasilan & keamanan finansial",q:"Selain besarnya, yang membuat penghasilan memberi rasa aman adalah...",options:["Merek pemberi kerja yang membayarmu, karena perusahaan besar menjamin penghasilan lancar dan sumber pendapatan tetap","Keteraturannya (bisa diprediksi), keberagamannya (beberapa sumber), & kebiasaan mengelola (menabung, menganggarkan) di sekitarnya","Hanya angka totalnya, karena stabilitas dan sumber penghasilan tak relevan bagi kesehatan keuangan seseorang di keluarga"],answer:1,explain:"Penghasilan besar yang tidak teratur & habis begitu masuk memberi keamanan lebih kecil daripada penghasilan sedang yang teratur & dikelola baik.",hint:"Mana yang lebih menenangkan: penghasilan besar sesekali yang langsung habis, atau penghasilan sedang yang teratur & ditabung?"},
{n:59,type:"mcq",micro:"Menghindari penipuan kerja",q:"Tawaran 'kerja dari rumah, gaji besar, tapi bayar dulu Rp200.000 untuk pendaftaran/alat'. Tanda bahaya:",options:["Wajar membayar di muka untuk memulai pekerjaan, karena perusahaan baik menyediakan alat dengan biaya pendaftaran resmi","Gaji besar berarti tawaran itu bagus dan terpercaya, jadi sebaiknya segera dibayar sebelum kuotanya habis untuk pelajar","Pekerjaan yang sah umumnya MEMBAYAR kamu, bukan meminta kamu membayar di muka untuk 'kesempatan' — ini pola penipuan klasik"],answer:2,explain:"Meminta biaya di muka untuk 'pekerjaan' bergaji besar adalah skema penipuan. Uang pendaftaran hilang & pekerjaannya tidak nyata.",hint:"Dalam pekerjaan biasa, siapa membayar siapa?"},
{n:60,type:"open",micro:"Menjelaskan pajak ke teman",q:"Seorang teman berkata: 'Pajak itu cuma pemerintah mengambil uang kita. Kalau bisa, hindari saja.' Tulis penjelasan (4–6 kalimat) yang mengoreksi anggapan ini, mencakup: apa yang dibiayai pajak, mengapa wajib (bukan sukarela), perbedaan menghindari secara sah vs mengelak, & mengapa kepatuhan + pengawasan keduanya penting.",explain:"Penjelasan baik menyebut: pajak membiayai layanan publik yang dipakai bersama; wajib karena mencegah 'menumpang gratis'; menghindari sah ≠ mengelak (ilegal & merugikan); & kepatuhan + pengawasan penggunaan keduanya penting untuk pajak yang bermanfaat.",hint:"Hubungkan pajak ke layanan konkret, jelaskan 'menumpang gratis', bedakan sah vs ilegal, & sebut peran pengawasan warga.",sample:"Contoh: 'Pajak memang berarti sebagian penghasilan kita masuk ke negara, tapi sebagian besar kembali sebagai hal yang kita & masyarakat pakai: jalan umum, sekolah negeri, rumah sakit pemerintah, polisi, pemadam kebakaran, penerangan jalan. Pajak wajib karena kalau sukarela, banyak orang tidak akan membayar padahal tetap memakai layanannya — jadi layanan itu tidak akan terbiayai. Ada bedanya antara memanfaatkan keringanan yang diizinkan hukum (sah) & menyembunyikan penghasilan atau memalsukan laporan (mengelak) — yang kedua melanggar hukum, bisa dipidana, & merugikan layanan untuk semua orang termasuk keluarga kita. Yang lebih tepat daripada 'menghindari saja' adalah membayar sesuai aturan DAN ikut mengawasi agar uang pajak dikelola dengan transparan & benar. Dengan begitu pajak jadi cara kita gotong royong membiayai hal yang tidak bisa dibeli sendiri-sendiri.'"},
{n:61,type:"mcq",micro:"Keadilan pajak progresif",q:"Argumen untuk pajak progresif (yang lebih mampu membayar persentase lebih besar):",options:["Rp100.000 pajak lebih berat bagi yang berpenghasilan Rp1 juta daripada bagi yang berpenghasilan Rp100 juta; persentase yang lebih tinggi untuk yang mampu membagi beban lebih adil","Setiap warga harus membayar jumlah rupiah yang sama persis, karena hanya itu cara yang dianggap adil, berapa pun besar penghasilannya, dan pemerintah tak perlu menghitung persentase","Yang miskin harus membayar persentase lebih besar, karena mereka lebih banyak memakai layanan publik gratis dari negara, tanpa dicek lagi pada akhirnya"],answer:0,explain:"Gagasan 'kemampuan membayar': dampak jumlah yang sama terasa berbeda tergantung penghasilan. Sistem nyata menyeimbangkan ini dengan pertimbangan lain (mendorong usaha, kesederhanaan).",hint:"Apakah Rp100.000 terasa sama beratnya bagi semua tingkat penghasilan?"},
{n:62,type:"tf",micro:"Sistem pajak melibatkan trade-off",q:"Benar atau Salah: Merancang sistem pajak melibatkan trade-off antara keadilan, kesederhanaan, mendorong orang bekerja & berusaha, & mengumpulkan cukup dana — tidak ada sistem yang sempurna di semua sisi.",answer:true,explain:"Pajak yang sangat progresif bisa terasa adil tapi rumit & mungkin mengurangi insentif; pajak rata sederhana tapi bisa terasa memberatkan yang kecil. Kebijakan mencari keseimbangan.",hint:"Bisakah satu sistem pajak sekaligus paling adil, paling sederhana, & paling mendorong usaha?"},
{n:63,type:"mcq",micro:"Penghasilan & pilihan karier",q:"Saat memikirkan karier masa depan, selain 'berapa penghasilannya', pertimbangan penting:",options:["Hanya gengsi dan nama besar pekerjaannya di mata teman dan tetangga, tanpa melihat minat dan kondisi kerjanya, serta prospek","Apakah pekerjaannya sesuai minat & nilaimu, kondisi kerjanya, keseimbangan hidup, & apakah bidang itu punya prospek — penghasilan penting tapi bukan satu-satunya","Hanya penghasilan yang penting, sedangkan minat, kondisi kerja, dan keseimbangan hidup tak perlu dipertimbangkan oleh pelajar yang baru memikirkan karier, sebab itu urusan nanti"],answer:1,explain:"Kepuasan & keberlanjutan karier bergantung pada banyak faktor. Penghasilan tinggi di pekerjaan yang membuat sengsara sering tidak sepadan.",hint:"Apakah pekerjaan bergaji tinggi yang kamu benci setiap hari adalah pilihan yang baik?"},
{n:64,type:"mcq",micro:"Penghasilan bukan ukuran nilai diri",q:"Menautkan harga diri semata pada besar penghasilan berisiko...",options:["Memotivasi karena orang jadi mau bekerja lebih keras tanpa memikirkan hal lain dalam hidupnya, sehingga baik dikembangkan di kelas dan di rumah","Tidak berisiko karena mengejar penghasilan tinggi tak pernah memengaruhi sikap terhadap orang lain yang berpenghasilan lebih kecil dari kita","Membuatmu tidak pernah merasa cukup, & merendahkan orang (termasuk diri sendiri) yang berpenghasilan lebih kecil meski bekerja jujur & keras"],answer:2,explain:"Penghasilan mencerminkan banyak faktor (bidang, kesempatan, keberuntungan), bukan hanya nilai atau kerja keras seseorang.",hint:"Apakah seorang guru yang hebat kurang berharga daripada seorang bankir hanya karena gajinya lebih kecil?"},
{n:65,type:"tf",micro:"Kesempatan penghasilan tidak merata",q:"Benar atau Salah: Peluang untuk mendapat penghasilan yang baik tersebar persis merata bagi semua orang & hanya bergantung pada usaha individu.",answer:false,explain:"Sebaliknya, peluang tidak merata — akses pendidikan, kesehatan, jaringan, & keadaan keluarga memengaruhinya, tidak hanya usaha. Usaha & keterampilan tetap penting, tapi menyadari perbedaan titik awal penting untuk empati & kebijakan yang memperluas kesempatan.",hint:"Apakah semua anak mulai dari garis start yang sama menuju penghasilan yang baik?"},
{n:66,type:"mcq",micro:"Etika: melaporkan penghasilan",q:"Seorang pekerja lepas menyembunyikan sebagian penghasilannya agar pajaknya lebih kecil. Ini...",options:["Mengelak pajak — melanggar hukum, tidak adil bagi yang jujur membayar, & mengurangi dana untuk layanan publik","Tindakan cerdas yang patut ditiru banyak orang, karena menyembunyikan penghasilan membuat uang yang dimiliki lebih banyak","Tidak masalah karena jumlah yang disembunyikan kecil, sebab aturan pajak hanya berlaku untuk penghasilan sangat besar"],answer:0,explain:"Menyembunyikan penghasilan adalah pelanggaran, terlepas dari jumlahnya. Ia memindahkan beban ke pembayar pajak yang jujur.",hint:"Kalau semua orang menyembunyikan penghasilannya, apa yang terjadi pada sekolah & jalan?"},
{n:67,type:"mcq",micro:"Penghasilan & tekanan sosial",q:"Tekanan untuk 'menghasilkan banyak & cepat' (dari media sosial, perbandingan) bisa mendorong orang ke...",options:["Tidak ada dampak karena keputusan keuangan di usia muda tak memengaruhi kehidupan saat dewasa, sehingga bisa diabaikan oleh pelajar","Skema cepat kaya yang berisiko/penipuan, utang untuk gaya hidup, atau mengabaikan pendidikan/keterampilan — perlu sikap kritis","Keputusan keuangan yang baik karena tawaran uang cepat menguntungkan pelajar yang mau mencoba dan tak takut rugi di awal"],answer:1,explain:"Narasi 'sukses instan' sering menyembunyikan risiko, keberuntungan, atau penipuan. Membangun penghasilan biasanya butuh keterampilan & waktu.",hint:"Apa yang biasanya disembunyikan oleh cerita 'cepat kaya' di media sosial?"},
{n:68,type:"tf",micro:"Bekerja saat pelajar: bermanfaat bila seimbang",q:"Benar atau Salah: Pekerjaan sampingan yang ringan & terkendali bisa mengajari pelajar tanggung jawab, mengelola uang, & keterampilan — selama tidak mengorbankan pendidikan, kesehatan, & keselamatan.",answer:true,explain:"Nilai pengalaman kerja pelajar sering besar, asal dalam batas yang melindungi hal-hal yang lebih penting untuk masa depannya.",hint:"Apa yang bisa diajarkan pekerjaan pertama selain uang, & apa syaratnya agar bermanfaat?"},
{n:69,type:"mcq",micro:"Penghasilan & tujuan jangka panjang",q:"Cara berpikir yang sehat tentang penghasilan pertama (uang saku atau kerja kecil):",options:["Untuk dihabiskan semuanya karena jumlahnya kecil, dan kebiasaan menabung baru perlu dipikirkan bila penghasilan sudah besar, jadi tak usah dilatih sekarang","Tidak perlu dipikirkan, sebab penghasilan pertama hanyalah uang tambahan yang tak berpengaruh pada kebiasaan nantinya sebagai pelajar","Sebagai kesempatan berlatih mengelola (menabung, menganggarkan) & belajar, bukan sekadar untuk dihabiskan — kebiasaan ini terbawa saat penghasilan membesar"],answer:2,explain:"Keterampilan mengelola uang dibangun lewat latihan pada jumlah berapa pun. Penghasilan kecil adalah 'lapangan latihan'.",hint:"Apa nilai terbesar dari uang pertama yang kamu kelola — jumlahnya, atau latihan mengelolanya?"},
{n:70,type:"order",micro:"Menilai sebuah peluang penghasilan",q:"Urutkan langkah menilai sebuah peluang menghasilkan uang.",items:["Perjelas apa yang ditawarkan: berapa, kapan dibayar, apa yang harus kamu lakukan/keluarkan","Cek tanda bahaya: minta bayar di muka? janji untung besar-cepat-dijamin? tidak jelas siapa/apa?","Hitung untung bersih realistis & biaya (waktu, uang, risiko)","Timbang terhadap alternatif (termasuk waktu untuk belajar/istirahat) & putuskan; kalau ragu, tanya orang dewasa tepercaya"],answer:[0,1,2,3],explain:"Perjelas tawaran → cek tanda bahaya → hitung untung bersih & biaya → timbang & putuskan (tanya bila ragu).",hint:"Sebelum menghitung untung, pastikan tawarannya jelas & bukan penipuan."},
{n:71,type:"mcq",micro:"Penghasilan & kontribusi sosial",q:"Beberapa pekerjaan bergaji sedang punya dampak sosial besar (guru, perawat, petugas kebersihan). Ini menunjukkan...",options:["Nilai sebuah pekerjaan bagi masyarakat tidak selalu tercermin dari besar gajinya — & pilihan karier bisa mempertimbangkan makna, bukan hanya uang","Pekerjaan itu tidak penting bagi masyarakat, karena gajinya sedang-sedang saja dan tidak banyak dibicarakan orang","Gaji mencerminkan nilai sosial pekerjaan, jadi pekerjaan yang bergaji kecil tak berguna bagi masyarakat menurut banyak orang, terutama di kota besar"],answer:0,explain:"Pasar tenaga kerja & nilai sosial tidak selalu sejalan. Sebagian orang memilih pekerjaan bermakna meski gajinya sedang.",hint:"Apakah pekerjaan yang paling penting bagi masyarakat selalu yang bergaji paling tinggi?"},
{n:72,type:"tf",micro:"Menghargai pekerjaan orang tua",q:"Benar atau Salah: Uang saku 'muncul begitu saja' & tidak ada kaitannya dengan waktu & tenaga kerja orang tua.",answer:false,explain:"Sebaliknya, uang saku mewakili jam kerja orang tua. Memahami ini membantu kita lebih menghargainya & lebih bijak membelanjakannya.",hint:"Berapa jam kerja yang diwakili oleh uang saku mingguanmu?"},
{n:73,type:"mcq",micro:"Penghasilan pasif: realistis",q:"Cerita 'penghasilan pasif tanpa kerja' sering menyesatkan karena...",options:["Banyak orang bisa langsung mendapatkannya tanpa modal, keterampilan, dan usaha di awal dengan mudah, bahkan sebagai pelajar dan tanpa perlu merawatnya","Hampir semua penghasilan pasif butuh modal, keterampilan, atau usaha besar di AWAL (menabung/berinvestasi bertahun-tahun, membuat karya, membeli aset), & pemeliharaan","Penghasilan pasif itu mustahil ada, sehingga semua cerita tentangnya bohong belaka dan harus dijauhi sepenuhnya, termasuk bunga tabungan"],answer:1,explain:"'Pasif' berarti tidak butuh kerja aktif harian SETELAH dibangun — bukan berarti gratis atau instan.",hint:"Dari mana datangnya bunga tabungan atau uang sewa — apakah benar-benar 'tanpa apa-apa di awal'?"},
{n:74,type:"mcq",micro:"Pajak & warga muda",q:"Meski pelajar belum membayar pajak penghasilan, memahami pajak sekarang berguna karena...",options:["Tidak berguna sampai kamu benar-benar bekerja, jadi sebaiknya baru dipelajari setelah menerima gaji pertamamu nanti, tanpa dicek lagi","Pajak tidak akan pernah relevan bagimu, sebab pelajar tidak mungkin berhubungan dengan pajak sampai kapan pun juga","Sebentar lagi kamu akan berpenghasilan & punya kewajiban; & sebagai warga, kamu ikut menentukan (lewat pilihan & suara) bagaimana pajak dikumpulkan & dipakai"],answer:2,explain:"Literasi pajak adalah keterampilan kewargaan: memahami sistem yang akan kamu ikuti & pengaruhi.",hint:"Kapan pemahaman tentang pajak mulai berguna: saat sudah terlambat, atau sebelumnya?"},
{n:75,type:"mcq",micro:"Penghasilan & keberlanjutan",q:"Penghasilan yang 'berkelanjutan' berarti...",options:["Bisa terus diperoleh dari waktu ke waktu (keterampilan yang tetap dibutuhkan, usaha yang sehat, aset yang terjaga) — bukan yang cepat habis atau bergantung pada satu keberuntungan","Penghasilan yang jumlahnya sangat besar dalam sekali terima, seperti hadiah undian atau warisan, yang langsung dinikmati, karena itu dianggap paling baik","Penghasilan yang tak dikenai pajak, sehingga seluruhnya bisa dibawa pulang tanpa dipotong"],answer:0,explain:"Membangun kemampuan berpenghasilan yang tahan lama lebih berharga daripada satu 'rezeki nomplok' yang tidak berulang.",hint:"Mana yang lebih berharga: menang undian sekali, atau keterampilan yang bisa menghasilkan seumur hidup?"},
{n:76,type:"tf",micro:"Penghasilan adalah alat, bukan tujuan akhir",q:"Benar atau Salah: Penghasilan adalah alat untuk mencapai hal yang kamu anggap penting (keamanan, kesempatan, membantu keluarga, hidup sesuai nilai) — bukan tujuan akhir yang dikejar tanpa batas.",answer:true,explain:"Mengejar penghasilan tanpa memikirkan untuk apa sering berujung kelelahan atau hidup yang tidak seimbang. Penghasilan melayani tujuan.",hint:"Untuk apa sebenarnya kamu ingin berpenghasilan?"},
{n:77,type:"mcq",micro:"Penghasilan & waktu yang tak tergantikan",q:"Menukar terlalu banyak waktu (istirahat, keluarga, belajar, kesehatan) untuk penghasilan tambahan bisa jadi...",options:["Tidak ada trade-off karena waktu istirahat dan belajar bisa diganti dengan uang","Tidak sepadan — sebagian hal yang dikorbankan tidak bisa dibeli kembali dengan uang","Keputusan terbaik karena penghasilan tambahan lebih penting daripada hal lain di sekolah"],answer:1,explain:"Waktu untuk kesehatan, hubungan, & pembelajaran punya nilai yang tidak selalu bisa 'dibeli ulang'. Keseimbangan penting.",hint:"Bisakah kamu membeli kembali kesehatan atau tahun-tahun bersama keluarga dengan uang lembur?"},
{n:78,type:"mcq",micro:"Menilai klaim 'penghasilan besar tanpa keterampilan'",q:"Iklan: 'Hasilkan Rp10 juta/bulan dari rumah tanpa keahlian, tanpa modal, tanpa risiko!' Sikap yang tepat:",options:["Percaya dan segera mendaftar, karena kesempatan sebesar itu jarang datang dan harus diambil sebelum orang lain melakukannya","Coba dulu saja, siapa tahu benar, karena kerugian mencoba paling hanya sedikit dan tidak perlu terlalu dicurigai","Sangat skeptis — 'besar + mudah + tanpa keahlian + tanpa risiko' hampir selalu berarti penipuan, skema piramida, atau hal ilegal"],answer:2,explain:"Penghasilan yang nyata & besar hampir selalu butuh keterampilan, modal, waktu, atau menanggung risiko. Klaim yang menghilangkan semua itu adalah tanda bahaya.",hint:"Kalau benar-benar semudah itu menghasilkan Rp10 juta/bulan, kenapa mereka repot mengiklankannya ke kamu?"},
{n:79,type:"mcq",micro:"Penghasilan & pilihan pendidikan",q:"Keputusan tentang melanjutkan pendidikan/pelatihan sebaiknya mempertimbangkan...",options:["Biaya & waktunya vs peningkatan peluang & penghasilan yang mungkin, minatmu, & jalur alternatif — sebuah keputusan investasi yang dipikirkan, bukan otomatis 'lebih tinggi selalu lebih baik' atau 'tidak usah'","Ambil pendidikan setinggi mungkin bagaimanapun biayanya, karena pendidikan tinggi menjamin penghasilan besar bagi banyak orang, tanpa menimbang jalur lain, biaya, ataupun minat pribadi","Tidak usah melanjutkan pendidikan atau pelatihan, karena sekolah tak memengaruhi penghasilan seseorang di kemudian hari bagi banyak orang, sebagaimana biasanya, dan itu terbukti"],answer:0,explain:"Pendidikan lanjutan adalah investasi dengan biaya & manfaat. Menimbangnya (termasuk jalur vokasi/keterampilan) lebih bijak daripada aturan otomatis.",hint:"Apa yang perlu ditimbang: biaya & waktu vs peluang & minat, bukan hanya 'gengsi'."},
{n:80,type:"open",micro:"Menganalisis keputusan kerja vs belajar",q:"Seorang teman kelas 9 ditawari pekerjaan tetap membantu bengkel keluarga temannya: penghasilan bagus (Rp1.500.000/bulan) tapi harus berhenti sekolah karena jamnya penuh. Ia berpikir 'lebih baik menghasilkan uang sekarang daripada sekolah'. Analisis: (1) apa yang menarik dari tawaran ini, (2) apa yang dikorbankan & risikonya jangka panjang, (3) adakah jalan tengah, (4) apa yang kamu sarankan & mengapa.",explain:"Jawaban baik mengakui daya tarik (uang & keterampilan sekarang), menjelaskan biaya & risiko jangka panjang putus sekolah (pilihan sempit, penghasilan sulit naik, sulit kembali belajar), menawarkan jalan tengah (kerja sampingan terbatas, jalur vokasi), & menyarankan tidak berhenti sekolah dengan alasan investasi pendidikan.",hint:"Bandingkan Rp1.500.000/bulan sekarang dengan puluhan tahun peluang yang dibuka (atau ditutup) oleh menyelesaikan pendidikan.",sample:"(1) Menarik: penghasilan langsung & lumayan; belajar keterampilan bengkel; merasa 'produktif' & mandiri sekarang. (2) Dikorbankan: menyelesaikan pendidikan dasar/menengah — yang membuka banyak pintu (pekerjaan lain, pelatihan lanjutan, sertifikasi) & keterampilan umum (membaca kritis, berhitung, komunikasi) yang berguna seumur hidup. Risiko jangka panjang: kalau bengkel tutup atau ia ingin ganti bidang, ijazah & keterampilan dasar yang tidak dimiliki membatasi pilihannya; penghasilan Rp1.500.000 mungkin terasa besar sekarang tapi sulit naik tanpa pendidikan/sertifikat; putus sekolah di usia muda sering menyulitkan kembali belajar nanti. (3) Jalan tengah: (a) tetap sekolah & bekerja di bengkel hanya sore/akhir pekan dengan jam terbatas; (b) selesaikan dulu jenjang wajib, lalu ambil pendidikan vokasi otomotif yang menggabungkan sekolah & praktik; (c) minta pemilik bengkel menyesuaikan jam agar tidak bentrok sekolah. (4) Saran: JANGAN berhenti sekolah. Pendidikan adalah investasi yang manfaatnya jauh melebihi Rp1.500.000/bulan sekarang, & putus sekolah di kelas 9 sangat membatasi masa depan. Kalau ia butuh/ingin uang & pengalaman bengkel, lakukan sebagai kerja sampingan terbatas yang tidak mengganggu sekolah, atau kejar lewat jalur vokasi setelah menyelesaikan jenjang wajib."},
{n:81,type:"mcq",micro:"Peta jenis penghasilan",q:"Ringkasan jenis penghasilan:",options:["Semua penghasilan sama saja sifatnya dan risikonya, sehingga tidak perlu dibedakan antara kerja, usaha, maupun penghasilan dari aset walaupun keadaan dan tujuan masing-masing orang sebenarnya berbeda","Kerja (upah/gaji — tukar waktu & keterampilan dengan bayaran); usaha (jual barang/jasa, ambil untung setelah biaya); pasif (dari aset/karya yang sudah dibangun — bunga, sewa, royalti) — masing-masing punya karakter & risiko berbeda","Hanya gaji bulanan dari perusahaan yang disebut penghasilan, sedangkan hasil jualan dan bunga tabungan tidak termasuk di dalamnya"],answer:1,explain:"Memahami ketiga jenis membantu merencanakan: kerja memberi keteraturan, usaha memberi potensi & risiko, pasif butuh dibangun dulu.",hint:"Gabungkan: kerja + usaha + pasif, masing-masing dengan sifatnya."},
{n:82,type:"mcq",micro:"Peta pajak",q:"Ringkasan pajak:",options:["Uang yang pemerintah ambil tanpa manfaat bagi warga, dan karena itu sebaiknya dihindari dengan segala cara, baik yang sah maupun yang tidak sah, supaya penghasilan tak berkurang dan tabungan keluarga tetap utuh untuk anak-cucu, termasuk lewat penyembunyian penghasilan","Sumbangan sukarela yang dibayar bila warga mau, sama seperti infak, tidak punya hubungan dengan penghasilan, tidak progresif, dan tidak perlu dilaporkan kepada petugas pajak setiap tahun, sehingga warga bebas menentukan sendiri jumlah dan waktunya","Iuran wajib warga & badan usaha kepada negara untuk membiayai layanan publik; sering progresif (yang mampu bayar persentase lebih besar); bruto − potongan (termasuk pajak & iuran) = neto; menghindari sah ≠ mengelak (ilegal); kepatuhan + pengawasan penggunaan keduanya penting"],answer:2,explain:"Pajak = pembiayaan bersama layanan publik; wajib; sering progresif; menghasilkan neto setelah potongan; menuntut kejujuran & akuntabilitas.",hint:"Gabungkan: wajib + untuk layanan publik + progresif + bruto/neto + sah vs mengelak + kepatuhan & pengawasan."},
{n:83,type:"tf",micro:"Penghasilan & keterampilan keuangan lain",q:"Benar atau Salah: Memahami penghasilan (jenisnya, bruto vs neto, keterkaitannya dengan keterampilan & pendidikan) adalah dasar untuk membuat anggaran, menabung, & merencanakan masa depan keuangan.",answer:true,explain:"Anggaran & rencana keuangan dimulai dari 'berapa yang benar-benar masuk & dari mana' — yaitu pemahaman tentang penghasilan.",hint:"Bisakah kamu membuat anggaran tanpa tahu penghasilan bersihmu?"},
{n:84,type:"mcq",micro:"Membangun potensi penghasilan sejak muda",q:"Hal paling berdampak yang bisa dilakukan pelajar untuk potensi penghasilan seumur hidupnya:",options:["Menyelesaikan pendidikan dengan sungguh-sungguh, mengembangkan keterampilan yang diminati & bernilai, membangun kebiasaan kerja & mengelola uang, & mencari pengalaman","Fokus mengumpulkan uang kecil sekarang dengan mengorbankan sekolah dan keterampilan, karena uang di tangan lebih jelas nilainya pada akhirnya","Menunggu 'kesempatan besar' datang sendiri tanpa belajar atau berlatih, sebab keberuntungan yang menentukan penghasilan seseorang di dunia kerja"],answer:0,explain:"'Modal manusia' (pendidikan + keterampilan + kebiasaan) adalah aset penghasilan terbesar bagi kebanyakan orang, & dibangun sejak muda.",hint:"Apa 'aset' yang paling menentukan penghasilan seumur hidup kebanyakan orang?"},
{n:85,type:"order",micro:"Dari pemasukan sampai rencana",q:"Urutkan langkah dari mendapat penghasilan sampai merencanakan pengeluarannya.",items:["Kenali sumber & jenis penghasilanmu (kerja/usaha/pasif) & keteraturannya","Hitung penghasilan BERSIH (setelah potongan/biaya)","Sisihkan tabungan & kewajiban (bayar diri sendiri dulu)","Alokasikan sisa ke kebutuhan & keinginan dalam anggaran; tinjau berkala"],answer:[0,1,2,3],explain:"Kenali sumber → hitung neto → sisihkan tabungan & kewajiban → anggarkan sisa & tinjau.",hint:"Kamu perlu tahu neto sebelum bisa membaginya."},
{n:86,type:"mcq",micro:"Penghasilan & kontribusi warga",q:"Sebagai warga berpenghasilan (nanti), tanggung jawab yang menyertainya:",options:["Tidak peduli pada penggunaan pajak, karena urusan itu sepenuhnya milik pemerintah dan warga cukup membayar saja","Membayar pajak sesuai aturan dengan jujur, menyimpan bukti/pencatatan, & ikut mengawasi agar dana publik dipakai dengan benar","Menghindari pajak dengan cara yang bisa dilakukan, termasuk menyembunyikan penghasilan, selama tak ketahuan petugas, demi menghemat uang"],answer:1,explain:"Kewargaan finansial mencakup kepatuhan yang jujur DAN partisipasi dalam menuntut akuntabilitas.",hint:"Apa dua sisi tanggung jawab warga terhadap pajak?"},
{n:87,type:"tf",micro:"Semua kerja jujur bermartabat",q:"Benar atau Salah: Martabat seseorang tidak ditentukan oleh besar penghasilan atau jenis pekerjaannya, selama pekerjaan itu jujur & halal.",answer:true,explain:"Menautkan martabat pada penghasilan merendahkan banyak pekerja penting & menciptakan tekanan yang tidak sehat.",hint:"Apakah seorang petani atau pedagang kecil kurang bermartabat daripada seorang eksekutif?"},
{n:88,type:"mcq",micro:"Menutup: penghasilan, kerja & pajak",q:"Sikap paling berguna:",options:["Kejar penghasilan sebesar mungkin dengan segala cara; hindari pajak; abaikan sekolah dan keterampilan; percaya pada setiap tawaran uang cepat yang ditemui; anggap bruto dan neto sama saja; dan jangan menabung maupun menganggarkan sampai penghasilanmu sudah besar nanti, karena itu urusan orang dewasa saja yang punya pekerjaan tetap","Penghasilan tak penting dan tak perlu dipikirkan, karena uang akan datang sendiri; pajak, keterampilan, dan pendidikan juga tak berpengaruh pada keamanan keuangan seseorang; menabung dan menganggarkan bisa ditunda sampai tua; dan janji cepat kaya layak dicoba karena pelajar punya banyak waktu untuk belajar dari kegagalan","Pahami dari mana penghasilanmu berasal (kerja/usaha/pasif) & bedakan bruto dari neto; bangun keterampilan & pendidikan sebagai aset penghasilan jangka panjang; kelola penghasilan dengan menabung & menganggarkan sejak jumlah kecil; pahami pajak sebagai pembiayaan bersama layanan publik & kewajiban yang dipenuhi dengan jujur; & waspadai penipuan & janji 'cepat kaya'"],answer:2,explain:"Inti: pahami sumber & neto + bangun keterampilan/pendidikan + kelola sejak dini + pajak sebagai kewajiban jujur & pembiayaan bersama + waspada penipuan.",hint:"Gabungkan: pahami sumber & neto + keterampilan sebagai aset + kelola sejak dini + pajak jujur + waspada penipuan."},
{n:89,type:"mcq",micro:"Ringkasan: penghasilan, kerja & pajak",q:"Rangkuman paling tepat:",options:["Penghasilan datang dari kerja, usaha, atau aset/karya (pasif); yang dipakai untuk anggaran adalah penghasilan bersih (bruto dikurangi pajak & iuran); keterampilan & pendidikan adalah aset penghasilan jangka panjang yang dibangun sejak muda; pajak adalah iuran wajib untuk membiayai layanan publik bersama, sering progresif, dipenuhi dengan pelaporan yang jujur, & disertai hak & tanggung jawab warga untuk mengawasi penggunaannya; & janji penghasilan 'besar-mudah-cepat-tanpa risiko' hampir selalu penipuan","Semua penghasilan sama saja sifatnya dan pajak hanyalah pemerintah mengambil uang warga tanpa manfaat; yang penting mengejar angka sebesar mungkin, tak perlu menimbang bruto dan neto, serta menerima janji uang cepat; keterampilan dan pendidikan tak berpengaruh pada penghasilan jangka panjang, dan anggaran sebaiknya disusun dari penghasilan kotor karena itu angka paling besar yang tampak di slip gaji setiap bulan, sehingga terasa lebih menenangkan bagi pelajar dan keluarga","Penghasilan hanya berarti gaji bulanan dari perusahaan; usaha dan aset tak dihitung, pelajar tak perlu mengembangkan keterampilan, pajak tak berhubungan dengan layanan publik, dan penipuan jarang terjadi; yang penting menerima gaji besar secepatnya, menyusun anggaran dari angka kotor, dan menganggap janji penghasilan besar yang mudah dan cepat sebagai peluang yang layak diambil sebelum diambil orang lain, sebagaimana kebanyakan orang dewasa lakukan"],answer:0,explain:"Jenis penghasilan + neto untuk anggaran + keterampilan sebagai aset + pajak sebagai pembiayaan bersama yang jujur & diawasi + waspada penipuan = inti.",hint:"Gabungkan: jenis + neto + keterampilan/pendidikan + pajak (wajib, progresif, jujur, diawasi) + waspada penipuan."},
{n:90,type:"tf",micro:"Kebiasaan mengelola dibangun dari penghasilan kecil",q:"Benar atau Salah: Kebiasaan mengelola uang tidak bisa dilatih dari jumlah kecil; seseorang baru bisa belajar mengatur uang setelah penghasilannya besar.",answer:false,explain:"Sebaliknya, keterampilan mengelola dilatih lewat pengulangan pada jumlah berapa pun. Kebiasaan menabung & menganggarkan dari uang saku cenderung terbawa & menguntungkan saat penghasilan membesar.",hint:"Apakah orang yang terbiasa mengatur sedikit tiba-tiba tidak bisa mengatur banyak?"},
{n:91,type:"mcq",micro:"Tiga prinsip praktis",q:"Tiga prinsip praktis tentang penghasilan, kerja & pajak:",options:["Abaikan penghasilan; jangan bekerja; jangan bayar pajak; dan percayakan masa depan pada keberuntungan tanpa membangun keterampilan, serta anggap tawaran uang cepat sebagai peluang bagus yang aman, sebab itu cara tercepat menuju kekayaan","Bedakan bruto dari neto & anggarkan dari neto; bangun keterampilan & pendidikan sebagai aset penghasilan jangka panjang (jangan korbankan sekolah untuk uang kecil sekarang); & pahami pajak sebagai kewajiban jujur yang membiayai layanan bersama, sambil mewaspadai penipuan 'cepat kaya'","Kejar uang sebesar mungkin sekarang walau mengorbankan sekolah; hindari pajak; dan percaya pada janji penghasilan besar yang mudah dan cepat dari orang yang menawarkan, sebab peluang seperti itu jarang datang dua kali dan sekolah bisa menunggu sampai kamu sudah kaya raya"],answer:1,explain:"Neto untuk anggaran + keterampilan/pendidikan sebagai aset + pajak jujur & waspada penipuan = inti praktis.",hint:"Gabungkan: neto untuk anggaran + keterampilan sebagai aset + pajak jujur & waspada penipuan."},
{n:92,type:"open",micro:"Kapstone: rencana penghasilan & pengelolaan",q:"Buat rencana pribadi tentang penghasilan & pengelolaannya. Sertakan: (1) sumber pemasukanmu sekarang & jenisnya, (2) satu keterampilan yang ingin kamu kembangkan untuk potensi penghasilan masa depan & bagaimana, (3) satu ide penghasilan sampingan yang aman & tidak mengganggu sekolah + perkiraan untung bersih, (4) bagaimana kamu membagi setiap pemasukan (tabungan/kewajiban dulu, lalu kebutuhan & keinginan), (5) apa yang kamu pahami tentang pajak & mengapa itu relevan untukmu nanti, (6) satu 'aturan kewaspadaan' terhadap tawaran/skema penghasilan yang mencurigakan.",explain:"Kapstone menggabungkan: mengenali sumber & jenis pemasukan, rencana membangun keterampilan sebagai aset penghasilan, ide sampingan dengan untung bersih & jadwal yang melindungi sekolah, pembagian pemasukan (tabungan/kewajiban dulu), pemahaman pajak & relevansinya, & aturan kewaspadaan terhadap penipuan.",hint:"Hubungkan semuanya: dari mana uang datang → keterampilan untuk masa depan → sampingan yang aman → bagi dengan tabungan dulu → paham pajak → waspada penipuan.",sample:"Contoh: (1) Pemasukan sekarang: uang saku dari orang tua (bukan penghasilan kerja, tapi kuperlakukan sebagai pemasukan untuk dikelola); kadang hadiah. (2) Keterampilan: desain grafis sederhana (poster, undangan) — belajar lewat tutorial gratis, latihan membuat poster untuk kegiatan sekolah, kumpulkan portofolio; targetnya bisa menerima pesanan kecil dari orang di sekitar dalam 6–12 bulan. (3) Ide sampingan: memberi les matematika untuk adik kelas, Rp20.000/sesi × 3/minggu = Rp60.000, biaya ~0 → untung bersih ~Rp58.000/minggu; dijadwalkan sore hari, dikurangi saat pekan ujian. (4) Pembagian tiap pemasukan: 25% ke tabungan/tujuan & dana darurat (disisihkan lebih dulu), 5% berbagi, sisanya untuk kebutuhan (transport, makan) & keinginan sesuai anggaran mingguan. (5) Pajak: aku belum membayar pajak penghasilan karena jauh di bawah batas, tapi aku paham pajak adalah iuran wajib untuk membiayai jalan, sekolah negeri, & layanan publik lain; nanti saat aku berpenghasilan di atas batas, aku wajib melaporkannya dengan jujur & tepat waktu, & sebagai warga aku juga berhak menuntut agar uang pajak dipakai dengan benar. (6) Aturan kewaspadaan: 'Kalau sebuah tawaran meminta aku membayar di muka, atau menjanjikan untung besar-cepat-dijamin-tanpa keahlian, aku menolak & bertanya ke orang tua — pekerjaan yang sah membayar aku, bukan sebaliknya.'"},
{n:93,type:"mcq",micro:"Menilai sebuah keputusan penghasilan",q:"Keputusan tentang penghasilan yang layak dipuji...",options:["Pilih pekerjaan yang bayarannya paling besar tanpa mempertimbangkan akibatnya pada sekolah, kesehatan, ataupun keamanan dirimu, sebagaimana biasanya, demi masa depan","Tolak semua peluang kerja yang datang, bahkan yang aman dan bermanfaat, karena sekolah harus menjadi kegiatan utama dan tunggal kamu, dan itu lebih aman bagi orang tuamu juga","Mempertimbangkan uang DAN pembelajaran/pengalaman DAN dampak pada sekolah/kesehatan; memakai neto untuk perencanaan; & menolak yang mencurigakan atau yang mengorbankan hal yang tidak tergantikan"],answer:2,explain:"Keputusan penghasilan yang baik menyeimbangkan uang, pertumbuhan, & biaya non-finansial — & jujur serta aman.",hint:"Apa saja yang perlu ditimbang selain angka bayaran?"},
{n:94,type:"mcq",micro:"Penghasilan & rasa cukup",q:"Setelah kebutuhan dasar & keamanan terpenuhi, penelitian umumnya menunjukkan tambahan penghasilan memberi tambahan kepuasan yang...",options:["Makin kecil — hubungan, tujuan, kesehatan, & makna menjadi lebih menentukan kesejahteraan","Sebanding — dua kali penghasilan berarti dua kali kebahagiaan, tanpa pengecualian pada orang","Negatif — makin kaya seseorang makin sengsara, sehingga menambah penghasilan sebaiknya dihindari"],answer:0,explain:"Uang penting sampai titik keamanan; setelahnya, mengejarnya tanpa henti sering kurang memuaskan daripada berinvestasi pada hubungan & makna.",hint:"Setelah kebutuhan & keamanan terpenuhi, apa yang lebih menentukan kesejahteraan seseorang?"},
{n:95,type:"tf",micro:"Literasi penghasilan & pajak adalah keterampilan kewargaan",q:"Benar atau Salah: Memahami penghasilan, dunia kerja, & pajak — meski kamu belum bekerja penuh — adalah bagian dari menjadi warga & orang dewasa yang cakap secara finansial.",answer:true,explain:"Pemahaman ini menyiapkanmu untuk keputusan karier, pengelolaan uang, & partisipasi sebagai warga yang tahu ke mana pajaknya pergi.",hint:"Kapan sebaiknya memahami dunia kerja & pajak: sebelum atau setelah kamu terjun ke dalamnya?"},
{n:96,type:"mcq",micro:"Penghasilan & ketidakadilan struktural",q:"Menyadari bahwa peluang penghasilan tidak tersebar merata (akses pendidikan, kesehatan, jaringan berbeda) mendorong kita untuk...",options:["Menyalahkan individu atas keadaan yang tidak mereka pilih, karena setiap orang punya peluang persis sama sejak lahir, jadi tak perlu dibantu","Berempati, tidak menghakimi orang dari besar penghasilannya, & mendukung upaya/kebijakan yang memperluas kesempatan bagi lebih banyak orang","Menyimpulkan bahwa usaha dan belajar tidak penting, sebab penghasilan hanya ditentukan oleh latar belakang keluarga seseorang saja"],answer:1,explain:"Usaha & keterampilan tetap penting, tapi mengakui perbedaan titik awal mendorong sikap yang lebih adil & solusi yang lebih luas.",hint:"Apakah semua orang mulai dari garis start yang sama menuju penghasilan yang baik?"},
{n:97,type:"mcq",micro:"Inti yang dibawa pulang",q:"Satu gagasan inti tentang penghasilan, kerja & pajak:",options:["Penghasilan adalah tujuan akhir hidup yang dikejar tanpa batas, dan pajak hanyalah beban yang sebaiknya dikurangi dengan segala cara yang mungkin, sedangkan keterampilan dan pendidikan hanya alat sementara bagi pelajar yang mencari pekerjaan pertamanya, dan mengelola uang boleh menunggu sampai kaya","Penghasilan hanya soal keberuntungan semata; keterampilan, pendidikan, dan cara mengelola uang sejak kecil tak berpengaruh pada keamanan maupun kebebasan seseorang, dan pajak tak ada hubungannya dengan layanan yang dinikmati warga, sehingga tak perlu dipenuhi dengan jujur setiap tahun","Penghasilan adalah hasil menukar nilai (waktu, keterampilan, produk) & alat untuk mencapai tujuan hidupmu; keterampilan & pendidikan adalah aset penghasilan terbesar; pajak adalah cara warga membiayai bersama layanan yang dinikmati semua; & mengelola penghasilan dengan bijak & jujur — sejak jumlah kecil — membangun keamanan & kebebasan"],answer:2,explain:"Penghasilan = pertukaran nilai & alat untuk tujuan; keterampilan/pendidikan = aset; pajak = pembiayaan bersama; kelola bijak & jujur sejak kecil.",hint:"Gabungkan: pertukaran nilai + alat untuk tujuan + keterampilan sebagai aset + pajak pembiayaan bersama + kelola bijak & jujur."},
{n:98,type:"mcq",micro:"Menghubungkan ke keterampilan lain",q:"Pemahaman tentang penghasilan menopang keterampilan keuangan lain karena...",options:["Anggaran, menabung, menghindari utang buruk, & berinvestasi semuanya dimulai dari 'berapa yang benar-benar masuk (neto) & dari mana' — yaitu penghasilan","Tak berhubungan dengan keterampilan keuangan lain, karena anggaran, tabungan, dan investasi bisa dipelajari tanpa mengetahui dari mana uang berasal","Hanya soal jumlah gaji yang diterima tiap bulan, sehingga bagi pelajar yang belum bekerja pemahaman itu belum berguna, jadi bisa ditunda"],answer:0,explain:"Semua perencanaan keuangan berdiri di atas pemahaman yang jelas tentang penghasilan bersih & sumbernya.",hint:"Dari mana setiap rencana keuangan dimulai?"},
{n:99,type:"tf",micro:"Pekerjaan pelajar harus melindungi hal yang lebih penting",q:"Benar atau Salah: Pekerjaan sampingan pelajar selalu bermanfaat, berapa pun jam kerjanya & seberapa pun ia mengorbankan sekolah, tidur, & kesehatan.",answer:false,explain:"Sebaliknya, pekerjaan pelajar hanya bermanfaat bila ringan, aman, dengan izin orang tua, & tidak mengorbankan pendidikan, kesehatan, & istirahat — 'investasi' terbesar pelajar yang lebih menentukan masa depan daripada uang kecil sekarang.",hint:"Apa yang lebih menentukan masa depan seorang pelajar: Rp50.000/minggu sekarang, atau pendidikan & kesehatannya?"},
{n:100,type:"open",micro:"Kapstone: panduan 'Penghasilan, Kerja & Pajak' untuk teman sebaya",q:"Tulis panduan singkat (8–10 poin) berjudul 'Penghasilan, Kerja & Pajak: Yang Perlu Kita Tahu' untuk teman sebayamu. Cakup: jenis penghasilan, bruto vs neto & anggaran dari neto, keterampilan & pendidikan sebagai aset penghasilan, pekerjaan pelajar (ringan, aman, izin orang tua, jangan ganggu sekolah), menyisihkan tabungan dari penghasilan pertama, apa itu pajak & untuk apa, kewajiban pajak yang jujur nanti, menghargai kerja orang tua, & mewaspadai penipuan 'cepat kaya'. Gunakan bahasa jelas & contoh.",explain:"Panduan baik menyederhanakan semua konsep: jenis penghasilan, bruto/neto & anggaran dari neto, keterampilan sebagai aset, batas kerja pelajar & pentingnya sekolah, menabung dari penghasilan pertama, untung usaha, pajak & untuk apa, kewajiban jujur nanti, menghargai kerja orang tua, & tanda penipuan — dengan bahasa & contoh ramah sebaya.",hint:"Tiap poin harus jelas & berguna untuk teman sebayamu, dari uang saku sekarang sampai pekerjaan pertama nanti.",sample:"Contoh panduan: 1) Penghasilan datang dari: KERJA (digaji/diupah orang lain), USAHA (jual barang/jasa, ambil untung setelah biaya), atau PASIF (dari aset/karya yang sudah dibangun, seperti bunga tabungan). 2) 'Bruto' = angka sebelum potongan; 'Neto' = yang benar-benar masuk setelah pajak & iuran. Buat anggaran dari NETO, bukan bruto. 3) Aset penghasilan terbesarmu adalah pendidikan & keterampilanmu — kembangkan keterampilan yang kamu minati & orang butuhkan. 4) Kerja sampingan pelajar boleh, tapi: ringan, aman, dengan izin orang tua, & TIDAK mengganggu belajar, istirahat, atau kesehatan. Selesaikan sekolah — jangan tukar dengan uang kecil sekarang. 5) Dari penghasilan pertama sekecil apa pun: sisihkan sebagian untuk tabungan SEBELUM belanja ('bayar diri sendiri dulu'). 6) Untuk usaha kecil, 'penghasilan'-mu adalah UNTUNG (penjualan − semua biaya), bukan seluruh uang penjualan. 7) Pajak adalah iuran wajib warga ke negara untuk membiayai jalan, sekolah negeri, rumah sakit pemerintah, polisi, & layanan lain yang kita pakai bersama. Wajib karena kalau sukarela, tidak akan terbiayai. 8) Nanti saat kamu berpenghasilan di atas batas tertentu, kamu wajib melaporkannya dengan jujur & tepat waktu — menyembunyikan penghasilan itu melanggar hukum & merugikan semua orang. 9) Uang sakumu mewakili jam kerja orang tuamu — hargai & kelola dengan bijak. 10) Waspada: tawaran 'penghasilan besar, mudah, cepat, tanpa keahlian, tanpa risiko' atau yang minta 'bayar di muka' hampir selalu penipuan. Pekerjaan yang sah MEMBAYAR kamu."},
];
